  V('A model is a useful “if”',p('<strong>If</strong> the cart keeps moving the same way, we can continue the pattern.',stem('I predict ___ because each second ___.')),R([0,2,4],'These are observations, not the next measurement.',[0,1,2]),'I do · name the pattern'),
  Q('One more second',p('At 0, 1, and 2 seconds, the cart is at 0, 2, and 4 m.','Predict its position at 3 seconds.'),R([0,2,4],'Continue the same change.',[0,1,2]),p('It reaches <strong>6 m</strong> if the pattern continues.')+math('4 m + 2 m = 6 m'),R([0,2,4,6],'Prediction: 6 m at 3 s.',[0,1,2,3])),
  V('Check the prediction',p('The prediction was 6 m.','Suppose the next reading is 5 m. We should check our measurements and model.'),plot('Prediction and a new reading',[{name:'Prediction',data:[[0,0],[1,2],[2,4],[3,6]]},{name:'New reading',data:[[3,5]]}],'Time (s)','Position (m)','A mismatch is a reason to investigate, not hide the measurement.'),'Think like a scientist'),
  Q('Which question can data answer?',p('A: Where will the object be tomorrow?','B: Who should pay for a mission?'),W([['Physics','Measurements and models.'],['A public decision','Values, resources, and priorities.']]),p('<strong>A</strong> can be investigated with position and motion data.','B also needs human decisions. A physics calculation alone cannot settle it.')),
  Q('Your turn: a different pattern',p('Positions are 2, 3, and 4 m, one second apart.','Predict the next position and explain.'),R([2,3,4],'Watch the change, not just the last number.',[0,1,2]),p('<strong>5 m.</strong> Each second adds 1 m.')+stem('My assumption is that the motion continues in the same way.'),R([2,3,4,5],'The model predicts 5 m.',[0,1,2,3]),'Try it yourself'),
  V('Build a useful question',stem('What measurements would help us find ___?')+p('Choose a quantity we can measure or predict.'),W([['Where?','Position.'],['How fast and which way?','Velocity.'],['When?','Time.']]),'Put it in words')
